buy_code:
매수 = True
if 데이터길이 < {min_len}:
    매수 = False
elif {b1_start} <= 시분초 < {b1_end}:
    if {b1_cap_lo} <= 시가총액 < {b1_cap_hi}:
        if not (등락율 >= {b1_rate_min} and 등락율 <= {b1_rate_max} and 분당거래대금 >= {b1_min_money} and 분당거래대금 >= 분당거래대금평균({b1_money_win}, 1) * {b1_money_burst} and 누적분당매수수량({b1_cum_win}) >= {b1_cum_buy_min} and 분당매수수량 >= (누적분당매수수량({b1_cum_win}) / {b1_cum_win}) * {b1_buy_velocity}):
            매수 = False
    else:
        매수 = False
elif {b2_start} <= 시분초 < {b2_end}:
    if {b2_cap_lo} <= 시가총액 < {b2_cap_hi}:
        if not (등락율 >= {b2_rate_min} and 등락율 <= {b2_rate_max} and 분당거래대금 >= {b2_min_money} and 분당거래대금 >= 분당거래대금평균({b2_money_win}, 1) * {b2_money_burst} and 현재가 >= 이동평균({b2_ma_win}, 1) * {b2_ma_reclaim} and 누적분당매수수량({b2_cum_win}) >= {b2_cum_buy_min} and 분당매수수량 >= (누적분당매수수량({b2_cum_win}) / {b2_cum_win}) * {b2_buy_velocity}):
            매수 = False
    else:
        매수 = False
else:
    매수 = False
if 매수:
    self.Buy()

sell_code:
매도 = False
if 수익률 >= {take_profit}:
    매도 = True
elif 수익률 <= -{stop_loss}:
    매도 = True
elif 보유시간 >= {max_hold_min}:
    매도 = True
elif 최고수익률 >= {trail_start} and 수익률 <= 최고수익률 - {trail_gap}:
    매도 = True
if 매도:
    self.Sell()
